SELECT COUNT(*) FROM ai_execution_evaluation WHERE project_id=#{projectId}
AND operational_status=#{operationalStatus}
AND business_verdict=#{businessVerdict}
AND executor_type=#{executorType}

mapper.update:
UPDATE ai_execution_evaluation
SET manual_score=#{score}, manual_comment=#{comment}, evaluated_by=#{evaluatedBy},
    evaluated_at=#{evaluatedAt}, updated_at=#{evaluatedAt}
WHERE task_id=#{taskId}

mapper.select:
SELECT id, task_id AS taskId, project_id AS projectId, score, comment,
       evaluated_by AS evaluatedBy, evaluated_at AS evaluatedAt
FROM ai_execution_evaluation_history
WHERE task_id=#{taskId}
ORDER BY evaluated_at DESC, id DESC
LIMIT #{limit}
